{
  "root_causes": [
    {
      "service": "ts-consign-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, span_name, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='ts-consign-service' AND attr_span_kind='Client' AND (span_name LIKE 'SELECT%' OR span_name LIKE 'INSERT%') GROUP BY ALL ORDER BY span_name, p", "claim": "ts-consign-service's SELECT/INSERT ts.consign_record client spans rose from ~1-2 ms p95 to ~1.7-3.3 s p95."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind kind, count(*) n, approx_quantile(duration/1e6, 0.95) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-consign-service','ts-consign-price-service') GROUP BY ALL ORDER BY service_name, n DESC", "claim": "Consign's own DB spans (Session.find, ConsignRepository.findById/save, Transaction.commit) take 1.7-11.6 s while sibling services' DB spans stay around 1 ms."},
        {"kind": "metric", "sql": "SELECT 'abn' p, metric, attr_k8s_pod_name pod, avg(value) avg_v, max(value) max_v FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'ts-consign-service%' AND metric IN ('container.cpu.usage','container.memory.working_set','k8s.container.restarts','k8s.pod.uptime') GROUP BY ALL", "claim": "Consign pod CPU, memory and restarts stay near normal levels, so the slowdown is not resource exhaustion or a restart."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-consign-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT p, span_name, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%consignservice%' GROUP BY ALL ORDER BY span_name, p", "claim": "Dashboard's consign endpoints slowed from ~30 ms to ~6 s p95 (account) and ~3.3 s (order), with PUT consigns near 20 s."}]}
  ]
}
